class_name TouchUI
extends Control
## On-screen controls for iPad. Writes into `state` (same keys as fighter input).

var state: Dictionary = {}
var touches: Dictionary = {}
var font: Font
var enabled: bool = false
var pause_pressed: bool = false
var pad_center: Vector2 = Vector2.ZERO
var buttons: Dictionary = {}
var flash: Dictionary = {}
var debug_log: bool = false
var special_label: String = "SPECIAL"

func _ready() -> void:
	font = load("res://assets/fonts/bangers.ttf")
	set_anchors_preset(Control.PRESET_FULL_RECT)
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	_clear()

func _clear() -> void:
	state = {"left": false, "right": false, "up": false, "down": false, "punch": false, "kick": false, "special": false, "block": false}

func layout() -> void:
	var vs: Vector2 = get_viewport().get_visible_rect().size
	pad_center = Vector2(190.0, vs.y - 190.0)
	buttons = {
		"punch": [Vector2(vs.x - 250.0, vs.y - 120.0), 62.0, "PUNCH", Color(1.0, 0.45, 0.2)],
		"kick": [Vector2(vs.x - 110.0, vs.y - 170.0), 62.0, "KICK", Color(0.3, 0.7, 1.0)],
		"special": [Vector2(vs.x - 210.0, vs.y - 265.0), 56.0, special_label, Color(1.0, 0.85, 0.2)],
		"block": [Vector2(vs.x - 80.0, vs.y - 310.0), 50.0, "BLOCK", Color(0.6, 0.6, 0.75)],
	}

func _input(event: InputEvent) -> void:
	if not enabled:
		return
	if event is InputEventScreenTouch:
		var e: InputEventScreenTouch = event
		if e.pressed:
			touches[e.index] = e.position
		else:
			touches.erase(e.index)
		_recompute()
	elif event is InputEventScreenDrag:
		var e2: InputEventScreenDrag = event
		touches[e2.index] = e2.position
		_recompute()

func _recompute() -> void:
	layout()
	_clear()
	var vs: Vector2 = get_viewport().get_visible_rect().size
	for k: Variant in touches.keys():
		var p: Vector2 = touches[k]
		# pause button (top right corner)
		if p.x > vs.x - 70.0 and p.y < 70.0:
			pause_pressed = true
			continue
		if p.x < vs.x * 0.45:
			var d: Vector2 = p - pad_center
			if d.length() < 170.0:
				if d.x < -34.0:
					state["left"] = true
				elif d.x > 34.0:
					state["right"] = true
				if d.y < -50.0:
					state["up"] = true
				elif d.y > 50.0:
					state["down"] = true
		else:
			for b: String in buttons.keys():
				var c: Vector2 = buttons[b][0]
				var r: float = float(buttons[b][1])
				if p.distance_to(c) < r + 14.0:
					state[b] = true
	if debug_log:
		var on: Array = []
		for k: String in state.keys():
			if state[k]:
				on.append(k)
		if not on.is_empty():
			print("touch: " + ",".join(on))
	queue_redraw()

func _draw() -> void:
	if not enabled:
		return
	layout()
	var vs: Vector2 = get_viewport().get_visible_rect().size
	# d-pad
	var pc: Vector2 = pad_center
	draw_circle(pc, 150.0, Color(0, 0, 0, 0.18))
	var arrows: Array = [["left", Vector2(-92, 0), PI], ["right", Vector2(92, 0), 0.0], ["up", Vector2(0, -92), -PI * 0.5], ["down", Vector2(0, 92), PI * 0.5]]
	for a: Array in arrows:
		var on: bool = bool(state[a[0]])
		var c: Vector2 = pc + (a[1] as Vector2)
		draw_circle(c, 44.0, Color(1, 1, 1, 0.55 if on else 0.22))
		draw_circle(c, 40.0, Color(0.1, 0.05, 0.15, 0.6))
		var ang: float = float(a[2])
		var tri: PackedVector2Array = PackedVector2Array([c + Vector2(cos(ang), sin(ang)) * 18.0, c + Vector2(cos(ang + 2.4), sin(ang + 2.4)) * 16.0, c + Vector2(cos(ang - 2.4), sin(ang - 2.4)) * 16.0])
		draw_colored_polygon(tri, Color(1, 1, 1, 0.95 if on else 0.75))
	# jump hint
	# buttons
	for b: String in buttons.keys():
		var c: Vector2 = buttons[b][0]
		var r: float = float(buttons[b][1])
		var col: Color = buttons[b][3]
		var on: bool = bool(state[b])
		draw_circle(c, r + 6.0, Color(0.08, 0.05, 0.12, 0.7))
		draw_circle(c, r, Color(col.r, col.g, col.b, 0.95 if on else 0.55))
		draw_circle(c + Vector2(-r * 0.25, -r * 0.3), r * 0.35, Color(1, 1, 1, 0.18))
		var txt: String = buttons[b][2]
		var fs: int = 22 if txt.length() > 5 else 26
		var w: float = font.get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
		draw_string(font, c + Vector2(-w * 0.5 + 2, 9 + 2), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(0.08, 0.05, 0.12))
		draw_string(font, c + Vector2(-w * 0.5, 9), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color.WHITE)
	# pause
	draw_circle(Vector2(vs.x - 36.0, 36.0), 26.0, Color(0, 0, 0, 0.4))
	draw_rect(Rect2(vs.x - 46.0, 24.0, 8.0, 24.0), Color.WHITE)
	draw_rect(Rect2(vs.x - 32.0, 24.0, 8.0, 24.0), Color.WHITE)

files.scripts/fighter.gd:
class_name Fighter
extends Node2D
## A procedurally drawn cartoon fighter with a small state machine.

const GRAVITY: float = 2600.0
var wall: float = 700.0
var hidden_in_cloud: bool = false
var bubble_text: String = ""
var bubble_t: float = 0.0

var data: Dictionary = {}
var attacks: Dictionary = Roster.attacks()
var facing: int = 1
var pos: Vector2 = Vector2.ZERO
var vel: Vector2 = Vector2.ZERO
var on_ground: bool = true
var hp: float = 100.0
var max_hp: float = 100.0
var meter: float = 0.0
var state: String = "idle"
var state_t: float = 0.0
var attack: Dictionary = {}
var attack_id: String = ""
var attack_hit: bool = false
var last_multi_hit: float = -1.0
var multi_hits: int = 0
var projectile_spawned: bool = false
var stun_t: float = 0.0
var down_t: float = 0.0
var crouching: bool = false
var blocking: bool = false
var opponent: Fighter = null
var input: Dictionary = {}
var prev_input: Dictionary = {}
var cur_pose: Dictionary = {}
var target_pose: Dictionary = {}
var walk_phase: float = 0.0
var squash: float = 1.0
var flash_t: float = 0.0
var life_t: float = 0.0
var combo_count: int = 0
var combo_timer: float = 0.0
var player_index: int = 0
var is_ai: bool = false
var size: float = 1.0
var speed: float = 300.0
var power: float = 1.0
var jump_mult: float = 1.0
var chain_buffer: String = ""
var combo_dmg: float = 0.0
var hits_taken_round: int = 0
var face_mood: String = "fierce"
var spin_angle: float = 0.0
var step_t: float = 0.0
var afterimages: Array = []
var ko_spin: float = 0.0
var knockdown_pending: bool = false

func setup(d: Dictionary, index: int) -> void:
	data = d
	player_index = index
	size = float(d.get("size", 1.0))
	speed = float(d.get("speed", 300.0))
	power = float(d.get("power", 1.0))
	jump_mult = float(d.get("jump", 1.0))
	max_hp = 100.0
	if d.get("boss", false):
		max_hp = 150.0
	hp = max_hp
	cur_pose = standing_pose()
	z_index = 5

func reset_round(x: float, face: int) -> void:
	pos = Vector2(x, 0)
	vel = Vector2.ZERO
	facing = face
	hp = max_hp
	on_ground = true
	state = "intro"
	state_t = 0.0
	attack = {}
	attack_id = ""
	stun_t = 0.0
	crouching = false
	blocking = false
	combo_count = 0
	combo_dmg = 0.0
	hits_taken_round = 0
	cur_pose = standing_pose()
	afterimages.clear()
	knockdown_pending = false
	queue_redraw()

func set_state(s: String) -> void:
	state = s
	state_t = 0.0

func standing_pose() -> Dictionary:
	return {
		"hip": Vector2(0, -78), "lean": 0.12, "head": Vector2(4, 0),
		"lh": Vector2(-14, -92), "rh": Vector2(34, -100),
		"lf": Vector2(-20, 0), "rf": Vector2(22, 0),
	}

func merge_pose(base: Dictionary, over: Dictionary) -> Dictionary:
	var p: Dictionary = base.duplicate()
	for k: String in over.keys():
		p[k] = over[k]
	return p

func lerp_pose(a: Dictionary, b: Dictionary, t: float) -> Dictionary:
	var p: Dictionary = {}
	for k: String in a.keys():
		var va: Variant = a[k]
		var vb: Variant = b.get(k, va)
		if va is Vector2:
			p[k] = (va as Vector2).lerp(vb as Vector2, t)
		else:
			p[k] = lerpf(float(va), float(vb), t)
	return p

func can_act() -> bool:
	return state in ["idle", "walk", "crouch", "block", "jump"]

func is_vulnerable() -> bool:
	return not (state in ["intro", "win", "lose", "ko", "down", "getup"])

func is_down() -> bool:
	return state in ["down", "getup", "ko"]

func in_hitstun() -> bool:
	return state in ["hit", "launched", "down", "ko"]

func pressed(k: String) -> bool:
	return bool(input.get(k, false)) and not bool(prev_input.get(k, false))

func held(k: String) -> bool:
	return bool(input.get(k, false))

func start_attack(id: String) -> bool:
	if not attacks.has(id):
		return false
	var a: Dictionary = attacks[id]
	if a.get("kind", "") == "special":
		if meter < 50.0:
			return false
		meter -= 50.0
	attack = a
	attack_id = id
	attack_hit = false
	multi_hits = 0
	last_multi_hit = -1.0
	projectile_spawned = false
	set_state("attack")
	crouching = bool(a.get("crouch", false))
	if a.has("rise"):
		vel.y = -float(a["rise"])
		on_ground = false
	var snd: String = String(a.get("snd", "whoosh"))
	if a.get("kind", "") == "special":
		if main().sfx:
			main().sfx.play(snd)
	else:
		if main().sfx:
			main().sfx.play_var("whoosh" if a.get("kind") == "punch" else "whoosh_big", -6.0)
	return true

func main() -> Node:
	return get_tree().current_scene

func attack_time() -> float:
	return state_t

## Called by main each frame (not during hitstop).
func tick(dt: float) -> void:
	life_t += dt
	state_t += dt
	flash_t = maxf(0.0, flash_t - dt)
	squash = lerpf(squash, 1.0, 1.0 - exp(-dt * 14.0))
	if combo_timer > 0.0:
		combo_timer -= dt
		if combo_timer <= 0.0:
			combo_count = 0
			combo_dmg = 0.0
	# facing: always look at opponent unless mid-attack / airborne
	if opponent and state in ["idle", "walk", "crouch", "block", "intro", "win", "lose"]:
		facing = 1 if opponent.pos.x >= pos.x else -1
	elif opponent == null and state in ["idle", "walk", "crouch", "block"]:
		if held("left"):
			facing = -1
		elif held("right"):
			facing = 1
	bubble_t = maxf(0.0, bubble_t - dt)
	var move_x: float = 0.0
	match state:
		"intro", "win", "lose":
			vel.x = 0.0
		"idle", "walk", "crouch", "block":
			_ground_control(dt)
		"jump":
			_air_control(dt)
		"attack":
			_attack_update(dt)
		"hit":
			vel.x = lerpf(vel.x, 0.0, 1.0 - exp(-dt * 10.0))
			if state_t >= stun_t:
				if on_ground:
					set_state("idle")
		"launched":
			pass
		"down":
			vel.x = lerpf(vel.x, 0.0, 1.0 - exp(-dt * 8.0))
			if state_t >= down_t:
				set_state("getup")
		"getup":
			if state_t >= 0.45:
				set_state("idle")
		"ko":
			vel.x = lerpf(vel.x, 0.0, 1.0 - exp(-dt * 6.0))
	# physics
	if not on_ground or vel.y < 0.0:
		vel.y += GRAVITY * dt
	pos += vel * dt
	if pos.y >= 0.0 and vel.y >= 0.0:
		var was_air: bool = not on_ground
		pos.y = 0.0
		vel.y = 0.0
		on_ground = true
		if was_air:
			_landed()
	else:
		if pos.y < 0.0:
			on_ground = false
	pos.x = clampf(pos.x, -wall, wall)
	# push apart
	if opponent and not is_down() and not opponent.is_down() and on_ground and opponent.on_ground:
		var min_d: float = 118.0 * (size + opponent.size) * 0.5
		var dx: float = opponent.pos.x - pos.x
		if absf(dx) < min_d:
			var push: float = (min_d - absf(dx)) * 0.5
			var dir: float = -1.0 if dx >= 0.0 else 1.0
			if absf(dx) < 1.0:
				dir = -1.0 if player_index == 0 else 1.0
			pos.x += dir * push
			opponent.pos.x -= dir * push
			pos.x = clampf(pos.x, -wall, wall)
			opponent.pos.x = clampf(opponent.pos.x, -wall, wall)
	position = pos
	# pose
	var target: Dictionary = pose_for_state()
	target_pose = target
	var k: float = 40.0 if state in ["attack", "hit", "launched", "ko"] else 14.0
	cur_pose = lerp_pose(cur_pose, target, 1.0 - exp(-dt * k))
	# afterimages
	if state == "attack" and attack.get("move", 0.0) > 0.0 and attack_time() >= float(attack["move_t"][0]) and attack_time() <= float(attack["move_t"][1]):
		if afterimages.is_empty() or (afterimages[-1]["pos"] as Vector2).distance_to(pos) > 26.0:
			afterimages.append({"pos": pos, "t": 0.0, "pose": cur_pose.duplicate(), "facing": facing})
	for i: int in range(afterimages.size() - 1, -1, -1):
		afterimages[i]["t"] = float(afterimages[i]["t"]) + dt
		if float(afterimages[i]["t"]) > 0.25:
			afterimages.remove_at(i)
	if state == "ko" and not on_ground:
		ko_spin += dt * 9.0
	queue_redraw()

func _landed() -> void:
	squash = 0.75
	if state == "launched" or (state == "ko"):
		if state == "launched":
			set_state("down")
			down_t = 0.75
			vel.x *= 0.3
		main().on_fighter_land(self, true)
	elif state == "jump" or (state == "attack" and attack.get("air", false)) or (state == "attack" and attack.has("rise") and state_t > 0.5):
		set_state("idle")
		main().on_fighter_land(self, false)
	elif state == "hit":
		set_state("idle")
	elif state == "attack":
		pass

func _ground_control(dt: float) -> void:
	var back: String = "left" if facing == 1 else "right"
	var fwd: String = "right" if facing == 1 else "left"
	crouching = held("down")
	blocking = (held("block") or held(back)) and not held(fwd)
	var mx: float = 0.0
	if held(fwd):
		mx = 1.0
	elif held(back):
		mx = -1.0
	# attacks
	if pressed("special"):
		if start_attack(String(data.get("special", "dash"))):
			return
		else:
			if main().sfx:
				main().sfx.play("block", -10.0, 0.6)
	if pressed("punch"):
		if start_attack("lowpunch" if crouching else "jab"):
			return
	if pressed("kick"):
		if start_attack("sweep" if crouching else "kick"):
			return
	if pressed("up") and not crouching:
		vel.y = -1000.0 * jump_mult
		vel.x = mx * speed * 0.9 * facing
		on_ground = false
		set_state("jump")
		squash = 1.2
		if main().sfx:
			main().sfx.play("jump", -8.0, randf_range(0.9, 1.1))
		return
	if crouching:
		vel.x = 0.0
		set_state_keep("crouch")
		return
	if held("block") and mx <= 0.0:
		vel.x = 0.0
		set_state_keep("block")
		return
	if mx != 0.0:
		vel.x = mx * speed * facing * (0.75 if mx < 0.0 else 1.0)
		set_state_keep("walk")
		walk_phase += dt * 12.0 * (speed / 300.0)
		step_t += dt
		if step_t > 0.28:
			step_t = 0.0
			if main().sfx:
				main().sfx.play("step", -16.0, randf_range(0.8, 1.2))
	else:
		vel.x = 0.0
		set_state_keep("idle")

func set_state_keep(s: String) -> void:
	if state != s:
		set_state(s)

func _air_control(dt: float) -> void:
	if pressed("punch"):
		start_attack("airpunch")
	elif pressed("kick"):
		start_attack("flykick")
	elif pressed("special") and meter >= 50.0 and String(data.get("special", "")) in ["spin", "rising"]:
		start_attack(String(data["special"]))

func _attack_update(dt: float) -> void:
	var t: float = attack_time()
	var dur: float = float(attack["dur"])
	var fwd: float = float(attack.get("fwd", 0.0))
	if attack.has("move"):
		var mt: Array = attack["move_t"]
		if t >= float(mt[0]) and t <= float(mt[1]):
			vel.x = float(attack["move"]) * facing
		else:
			vel.x = lerpf(vel.x, 0.0, 1.0 - exp(-dt * 20.0))
	else:
		vel.x = (fwd / dur) * facing * (2.0 if t < dur * 0.5 else 0.0)
	# buffer chain
	if pressed("punch"):
		chain_buffer = "punch"
	if pressed("kick"):
		chain_buffer = "kick"
	var cancel: float = float(attack.get("cancel", 99.0))
	if attack_hit and t >= cancel and chain_buffer != "":
		var nxt: String = String(attack.get("next", ""))
		if chain_buffer == "kick" and on_ground and not crouching:
			nxt = "kick"
		if nxt != "":
			chain_buffer = ""
			start_attack(nxt)
			return
	if t >= dur:
		chain_buffer = ""
		if on_ground:
			set_state("crouch" if held("down") else "idle")
		else:
			set_state("jump")
	elif t >= dur * 0.6:
		chain_buffer = ""

func hurt_capsule() -> Array:
	var h: float = 165.0 * size
	if crouching or state == "crouch":
		h = 115.0 * size
	if is_down() or state == "ko":
		h = 50.0 * size
	return [pos, pos + Vector2(0, -h), 32.0 * size]

func limb_world(name: String) -> Vector2:
	var src: Dictionary = target_pose if not target_pose.is_empty() else cur_pose
	var lp: Vector2 = src.get(name, Vector2.ZERO)
	return pos + Vector2(lp.x * facing, lp.y) * size

func head_world() -> Vector2:
	var sh: Vector2 = _shoulder(cur_pose)
	var lean: float = float(cur_pose["lean"])
	var up: Vector2 = Vector2(sin(lean), -cos(lean))
	var hc: Vector2 = sh + up * 30.0 + Vector2(cur_pose["head"])
	return pos + Vector2(hc.x * facing, hc.y) * size

## Apply a hit. Returns dict {blocked, dmg}
func take_hit(a: Dictionary, from: Fighter, point: Vector2, is_last_multi: bool = true) -> Dictionary:
	var low: bool = bool(a.get("crouch", false))
	var can_block: bool = state in ["idle", "walk", "crouch", "block"] and blocking and on_ground
	if can_block and low and not crouching:
		can_block = false
	var kb: Vector2 = a["kb"]
	var res: Dictionary = {"blocked": false, "dmg": 0.0, "point": point}
	if can_block:
		vel.x = kb.x * 0.6 * from.facing
		meter = minf(100.0, meter + 3.0)
		from.meter = minf(100.0, from.meter + 2.0)
		res["blocked"] = true
		set_state("block")
		stun_t = 0.15
		face_mood = "fierce"
		return res
	var dmg: float = float(a["dmg"]) * from.power
	if from.combo_count >= 3:
		dmg *= 0.85
	hp = maxf(0.0, hp - dmg)
	hits_taken_round += 1
	meter = minf(100.0, meter + 5.0)
	from.meter = minf(100.0, from.meter + 8.0)
	flash_t = 0.12
	face_mood = "ouch"
	res["dmg"] = dmg
	if in_hitstun() and not is_down():
		from.combo_count += 1
	else:
		from.combo_count = 1
		from.combo_dmg = 0.0
	from.combo_dmg += dmg
	from.combo_timer = 1.2
	attack = {}
	chain_buffer = ""
	crouching = false
	var knockdown: bool = bool(a.get("knockdown", false)) or bool(a.get("launch", false))
	if bool(a.get("knockdown_last", false)) and is_last_multi:
		knockdown = true
	if hp <= 0.0:
		set_state("ko")
		vel = Vector2(maxf(absf(kb.x), 380.0) * from.facing, -minf(kb.y, -520.0))
		on_ground = false
		ko_spin = 0.0
		return res
	if knockdown or (not on_ground and kb.y < -200.0):
		set_state("launched")
		vel = Vector2(kb.x * from.facing, kb.y if kb.y < -150.0 else -380.0)
		on_ground = false
	elif not on_ground:
		set_state("launched")
		vel = Vector2(kb.x * from.facing * 0.8, -300.0)
	else:
		set_state("hit")
		stun_t = float(a["stun"])
		vel = Vector2(kb.x * from.facing, minf(0.0, kb.y))
		if kb.y < -100.0:
			on_ground = false
	return res

func pose_for_state() -> Dictionary:
	var sp: Dictionary = standing_pose()
	var t: float = state_t
	var breath: float = sin(life_t * 3.0) * 2.0
	match state:
		"intro":
			var p: Dictionary = merge_pose(sp, {"rh": Vector2(44, -178 + sin(life_t * 8.0) * 12.0), "lh": Vector2(-20, -70), "lean": 0.05})
			if t > 1.2:
				p = sp
			return p
		"idle":
			return merge_pose(sp, {"hip": Vector2(0, -78 + breath), "rh": Vector2(34 + sin(life_t * 3.0) * 3.0, -100 + breath), "lh": Vector2(-14, -92 + breath)})
		"walk":
			var w: float = walk_phase
			var back_pedal: bool = (vel.x * facing) < 0.0
			var ph: float = w if not back_pedal else -w
			return merge_pose(sp, {
				"hip": Vector2(0, -80 + absf(sin(ph)) * 4.0), "lean": 0.18,
				"lf": Vector2(-20 + 22.0 * sin(ph), -maxf(0.0, sin(ph)) * 16.0),
				"rf": Vector2(22 + 22.0 * sin(ph + PI), -maxf(0.0, sin(ph + PI)) * 16.0),
				"rh": Vector2(36, -100 + sin(ph * 2.0) * 3.0), "lh": Vector2(-16, -92),
			})
		"crouch":
			return merge_pose(sp, {"hip": Vector2(-4, -46), "lean": 0.35, "lh": Vector2(-10, -70), "rh": Vector2(30, -74), "lf": Vector2(-26, 0), "rf": Vector2(26, 0), "head": Vector2(2, 2)})
		"block":
			var crouch_block: bool = crouching
			if crouch_block:
				return merge_pose(sp, {"hip": Vector2(-4, -46), "lean": 0.3, "lh": Vector2(22, -84), "rh": Vector2(26, -66), "lf": Vector2(-26, 0), "rf": Vector2(26, 0)})
			return merge_pose(sp, {"hip": Vector2(-4, -78), "lean": 0.05, "lh": Vector2(26, -118), "rh": Vector2(30, -92), "head": Vector2(-2, 2)})
		"jump":
			var rising: bool = vel.y < 0.0
			return merge_pose(sp, {"hip": Vector2(0, -84), "lean": 0.1 if rising else 0.0,
				"lf": Vector2(-16, -36 if rising else -20), "rf": Vector2(18, -40 if rising else -16),
				"rh": Vector2(30, -130 if rising else -96), "lh": Vector2(-24, -110 if rising else -80)})
		"attack":
			return attack_pose(sp, t)
		"hit":
			var s: float = clampf(t / maxf(0.05, stun_t), 0.0, 1.0)
			var mag: float = 1.0 - s
			return merge_pose(sp, {"hip": Vector2(-10 * mag, -78), "lean": -0.5 * mag, "head": Vector2(-10 * mag, 4 * mag),
				"lh": Vector2(-40 * mag - 10, -120 * mag - 20), "rh": Vector2(10, -70 - 50 * mag), "lf": Vector2(-28, 0), "rf": Vector2(16, 0)})
		"launched":
			return {"hip": Vector2(-10, -70), "lean": -1.0, "head": Vector2(-6, 6), "lh": Vector2(-60, -90), "rh": Vector2(-10, -110), "lf": Vector2(-30, -40), "rf": Vector2(30, -60)}
		"down":
			return {"hip": Vector2(-20, -16), "lean": -1.5, "head": Vector2(0, 4), "lh": Vector2(-90, -10), "rh": Vector2(-40, -26), "lf": Vector2(24, 0), "rf": Vector2(52, 0)}
		"getup":
			var s: float = clampf(t / 0.45, 0.0, 1.0)
			return lerp_pose({"hip": Vector2(-20, -16), "lean": -1.5, "head": Vector2(0, 4), "lh": Vector2(-90, -10), "rh": Vector2(-40, -26), "lf": Vector2(24, 0), "rf": Vector2(52, 0)}, sp, s)
		"ko":
			if on_ground:
				return {"hip": Vector2(-20, -16), "lean": -1.5, "head": Vector2(0, 6), "lh": Vector2(-96, -6), "rh": Vector2(-50, -30), "lf": Vector2(28, 0), "rf": Vector2(56, 0)}
			return {"hip": Vector2(-10, -70), "lean": -1.2, "head": Vector2(-6, 6), "lh": Vector2(-70, -80), "rh": Vector2(-20, -120), "lf": Vector2(-30, -50), "rf": Vector2(36, -62)}
		"win":
			var b: float = absf(sin(life_t * 6.0))
			return merge_pose(sp, {"hip": Vector2(0, -80 - b * 14.0), "lean": -0.05, "rh": Vector2(26, -200 - b * 10.0), "lh": Vector2(-26, -200 - b * 10.0), "lf": Vector2(-18, -b * 12.0), "rf": Vector2(20, -b * 12.0), "head": Vector2(0, -4)})
		"lose":
			return {"hip": Vector2(-4, -40), "lean": 0.45, "head": Vector2(6, 10), "lh": Vector2(-30, -40), "rh": Vector2(40, -40), "lf": Vector2(-36, 0), "rf": Vector2(44, 0)}
	return sp

func attack_pose(sp: Dictionary, t: float) -> Dictionary:
	var keys: Array = attack["keys"]
	if keys.is_empty():
		return sp
	var base: Dictionary = sp
	if attack.get("crouch", false):
		base = merge_pose(sp, {"hip": Vector2(-4, -46), "lean": 0.35, "lh": Vector2(-10, -70), "rh": Vector2(30, -74), "lf": Vector2(-26, 0), "rf": Vector2(26, 0)})
	if attack.get("air", false):
		base = merge_pose(sp, {"hip": Vector2(0, -84), "lf": Vector2(-16, -30), "rf": Vector2(18, -34)})
	var p: Dictionary = merge_pose(base, keys[0][1])
	for i: int in range(keys.size() - 1):
		var t0: float = float(keys[i][0])
		var t1: float = float(keys[i + 1][0])
		if t >= t0 and t <= t1:
			var a: Dictionary = merge_pose(base, keys[i][1])
			var b: Dictionary = merge_pose(base, keys[i + 1][1])
			var f: float = (t - t0) / maxf(0.0001, t1 - t0)
			f = f * f * (3.0 - 2.0 * f)
			p = lerp_pose(a, b, f)
			break
		if t > t1:
			p = merge_pose(base, keys[i + 1][1])
	if attack.get("spin", false):
		spin_angle = t * 22.0
		var r: float = 70.0
		p["rf"] = Vector2(cos(spin_angle) * r + 10.0, -70 + sin(spin_angle) * 20.0)
		p["lf"] = Vector2(cos(spin_angle + PI) * r * 0.5 - 10.0, -30 + sin(spin_angle + PI) * 10.0)
		p["rh"] = Vector2(cos(spin_angle + 1.5) * 50.0, -120)
		p["lh"] = Vector2(cos(spin_angle + 1.5 + PI) * 50.0, -118)
	return p

# ----------------------------------------------------------------- drawing
func _shoulder(p: Dictionary) -> Vector2:
	var hip: Vector2 = p["hip"]
	var lean: float = float(p["lean"])
	return hip + Vector2(sin(lean), -cos(lean)) * 58.0

func _ik(a: Vector2, b: Vector2, l1: float, l2: float, bend: float) -> Vector2:
	var d: Vector2 = b - a
	var dist: float = clampf(d.length(), 1.0, l1 + l2 - 0.5)
	var dir: Vector2 = d / maxf(0.001, d.length())
	var cosang: float = clampf((l1 * l1 + dist * dist - l2 * l2) / (2.0 * l1 * dist), -1.0, 1.0)
	var ang: float = acos(cosang)
	return a + dir.rotated(ang * bend) * l1

func col(c: Color) -> Color:
	if flash_t > 0.0:
		return c.lerp(Color(1, 1, 1), 0.85)
	return c

func say(text: String, life: float = 1.2) -> void:
	bubble_text = text
	bubble_t = life

func _draw() -> void:
	if hidden_in_cloud:
		return
	# afterimages
	for ai: Dictionary in afterimages:
		var a: float = 1.0 - float(ai["t"]) / 0.25
		var off: Vector2 = (ai["pos"] as Vector2) - pos
		draw_set_transform(Vector2(off.x, off.y), 0.0, Vector2(float(ai["facing"]) * size, size))
		_draw_body(ai["pose"], Color(data["accent"], 0.35 * a), true)
	draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
	# shadow
	var sh_y: float = -pos.y
	var sh_scale: float = clampf(1.0 - (-pos.y) / 900.0, 0.4, 1.0)
	draw_set_transform(Vector2(0, sh_y), 0.0, Vector2(sh_scale * size, sh_scale * size * 0.35))
	draw_circle(Vector2.ZERO, 46.0, Color(0, 0, 0, 0.28))
	var sq: Vector2 = Vector2(2.0 - squash, squash)
	var rot: float = 0.0
	if state == "ko" and not on_ground:
		rot = ko_spin * facing
	draw_set_transform(Vector2.ZERO, rot, Vector2(float(facing) * size * sq.x, size * sq.y))
	_draw_body(cur_pose, Color.WHITE, false)
	# stars when down / ko
	if state in ["down", "ko", "getup"]:
		draw_set_transform(Vector2.ZERO, 0.0, Vector2(float(facing) * size, size))
		var hc: Vector2 = _head_center(cur_pose)
		for i: int in range(4):
			var ang: float = life_t * 5.0 + i * TAU / 4.0
			var sp: Vector2 = hc + Vector2(cos(ang) * 40.0, -34.0 + sin(ang) * 10.0)
			_draw_star(sp, 9.0, Color(1.0, 0.9, 0.2), life_t * 3.0 + i)
	draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
	if bubble_t > 0.0 and bubble_text != "":
		_draw_bubble()

func _draw_bubble() -> void:
	var f: Font = load("res://assets/fonts/bangers.ttf")
	var fs: int = 30
	var w: float = f.get_string_size(bubble_text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
	var hc: Vector2 = head_world() - pos
	var pop: float = 1.0 + 0.25 * maxf(0.0, bubble_t - 0.9) * 4.0 if bubble_t > 0.9 else 1.0
	var bw: float = (w + 36.0) * pop
	var bh: float = 54.0 * pop
	var bx: float = hc.x + 20.0 * facing
	if bx + bw * 0.5 > 0.0 and facing == 1:
		pass
	var r: Rect2 = Rect2(Vector2(bx - bw * 0.5, hc.y - 70.0 - bh), Vector2(bw, bh))
	var dark: Color = Color(0.08, 0.05, 0.1)
	draw_rect(Rect2(r.position - Vector2(4, 4), r.size + Vector2(8, 8)), dark)
	draw_rect(r, Color.WHITE)
	var tail: PackedVector2Array = PackedVector2Array([Vector2(bx - 10, r.end.y - 2), Vector2(bx + 14, r.end.y - 2), Vector2(hc.x + 6 * facing, hc.y - 36)])
	draw_colored_polygon(PackedVector2Array([tail[0] + Vector2(-5, 0), tail[1] + Vector2(5, 0), tail[2] + Vector2(0, 8)]), dark)
	draw_colored_polygon(tail, Color.WHITE)
	draw_string(f, Vector2(r.position.x + 18.0 * pop, r.position.y + bh * 0.5 + 11.0), bubble_text, HORIZONTAL_ALIGNMENT_LEFT, -1, int(fs * pop), dark)

func _head_center(p: Dictionary) -> Vector2:
	var sh: Vector2 = _shoulder(p)
	var lean: float = float(p["lean"])
	var up: Vector2 = Vector2(sin(lean), -cos(lean))
	return sh + up * 32.0 + Vector2(p["head"])

func _draw_star(c: Vector2, r: float, color: Color, rot: float) -> void:
	var pts: PackedVector2Array = PackedVector2Array()
	for i: int in range(10):
		var rr: float = r if i % 2 == 0 else r * 0.45
		var a: float = rot + i * PI / 5.0
		pts.append(c + Vector2(cos(a), sin(a)) * rr)
	draw_colored_polygon(pts, color)

func _thick(a: Vector2, b: Vector2, w: float, c: Color, outline: bool = true) -> void:
	if outline:
		draw_line(a, b, Color(0.08, 0.05, 0.1), w + 7.0)
		draw_circle(a, (w + 7.0) * 0.5, Color(0.08, 0.05, 0.1))
		draw_circle(b, (w + 7.0) * 0.5, Color(0.08, 0.05, 0.1))
	draw_line(a, b, c, w)
	draw_circle(a, w * 0.5, c)
	draw_circle(b, w * 0.5, c)

func _draw_body(p: Dictionary, tint: Color, ghost: bool) -> void:
	var skin: Color = col(data["skin"]) * tint
	var torso_c: Color = col(data["torso"]) * tint
	var legs_c: Color = col(data["legs"]) * tint
	var glove_c: Color = col(data["glove"]) * tint
	var boot_c: Color = col(data["boot"]) * tint
	var hair_c: Color = col(data["hair"]) * tint
	var outline: Color = Color(0.08, 0.05, 0.1) * tint
	if ghost:
		skin = tint; torso_c = tint; legs_c = tint; glove_c = tint; boot_c = tint; hair_c = tint; outline = tint
	var hip: Vector2 = p["hip"]
	var lean: float = float(p["lean"])
	var up: Vector2 = Vector2(sin(lean), -cos(lean))
	var right: Vector2 = Vector2(cos(lean), sin(lean))
	var sh: Vector2 = hip + up * 58.0
	var l_hip: Vector2 = hip + Vector2(-9, 4)
	var r_hip: Vector2 = hip + Vector2(9, 4)
	var l_sh: Vector2 = sh + right * -16.0 + up * -4.0
	var r_sh: Vector2 = sh + right * 16.0 + up * -4.0
	var lf: Vector2 = p["lf"]
	var rf: Vector2 = p["rf"]
	var lh: Vector2 = p["lh"]
	var rh: Vector2 = p["rh"]
	var leg_w: float = 20.0
	var arm_w: float = 15.0
	var k_l: Vector2 = _ik(l_hip, lf + Vector2(0, -8), 44.0, 42.0, -1.0)
	var k_r: Vector2 = _ik(r_hip, rf + Vector2(0, -8), 44.0, 42.0, -1.0)
	var e_l: Vector2 = _ik(l_sh, lh, 34.0, 32.0, 1.0)
	var e_r: Vector2 = _ik(r_sh, rh, 34.0, 32.0, 1.0)
	var ol: bool = not ghost
	# back leg
	_thick(l_hip, k_l, leg_w, legs_c, ol)
	_thick(k_l, lf + Vector2(0, -8), leg_w, legs_c, ol)
	_draw_foot(lf, boot_c, outline, ol)
	# back arm
	_thick(l_sh, e_l, arm_w, torso_c if data.get("hairstyle") != "mask" else skin, ol)
	_thick(e_l, lh, arm_w, skin, ol)
	_draw_glove(lh, glove_c, outline, ol)
	# torso
	var pts: PackedVector2Array = PackedVector2Array([
		hip + right * -26.0 + up * -6.0, hip + right * 26.0 + up * -6.0, hip + right * 24.0 + up * 8.0, hip + right * 22.0 + up * 22.0,
		sh + right * 30.0 + up * -6.0, sh + right * 34.0 + up * 6.0, sh + right * 26.0 + up * 16.0,
		sh + right * -26.0 + up * 16.0, sh + right * -34.0 + up * 6.0, sh + right * -30.0 + up * -6.0,
		hip + right * -22.0 + up * 22.0, hip + right * -24.0 + up * 8.0])
	if ol:
		var opts: PackedVector2Array = PackedVector2Array()
		var cen: Vector2 = (hip + sh) * 0.5
		for v: Vector2 in pts:
			opts.append(cen + (v - cen) * 1.14 + Vector2(0, 0))
		draw_colored_polygon(opts, outline)
	draw_colored_polygon(pts, torso_c)
	if not ghost:
		# shorts / lower body colour and a highlight
		draw_colored_polygon(PackedVector2Array([hip + right * -26.0 + up * -6.0, hip + right * 26.0 + up * -6.0, hip + right * 24.0 + up * 8.0, hip + right * -24.0 + up * 8.0]), legs_c)
		draw_line(sh + right * -20.0 + up * 8.0, hip + right * -16.0 + up * 12.0, Color(1, 1, 1, 0.14), 8.0)
		# belt + emblem
		draw_line(hip + right * -22.0 + up * 2.0, hip + right * 22.0 + up * 2.0, col(data["accent"]), 6.0)
		draw_circle(sh + up * -16.0, 9.0, col(data["accent"]))
		draw_circle(sh + up * -16.0, 4.0, outline)
	# front leg
	_thick(r_hip, k_r, leg_w, legs_c, ol)
	_thick(k_r, rf + Vector2(0, -8), leg_w, legs_c, ol)
	_draw_foot(rf, boot_c, outline, ol)
	# head
	var hc: Vector2 = sh + up * 32.0 + Vector2(p["head"])
	_thick(sh, sh + up * 12.0, 16.0, skin, ol)
	if ol:
		draw_circle(hc, 30.0, outline)
	draw_circle(hc, 26.0, skin)
	if not ghost:
		_draw_face(hc, lean)
		_draw_hair(hc, hair_c, outline, skin)
	# front arm
	_thick(r_sh, e_r, arm_w, torso_c if data.get("hairstyle") != "mask" else skin, ol)
	_thick(e_r, rh, arm_w, skin, ol)
	_draw_glove(rh, glove_c, outline, ol)

func _draw_glove(h: Vector2, c: Color, outline: Color, ol: bool) -> void:
	if ol:
		draw_circle(h, 17.0, outline)
	draw_circle(h, 13.5, c)
	if ol:
		draw_circle(h + Vector2(-4, -5), 4.0, Color(1, 1, 1, 0.45))

func _draw_foot(f: Vector2, c: Color, outline: Color, ol: bool) -> void:
	var r: Rect2 = Rect2(f + Vector2(-14, -16), Vector2(34, 16))
	if ol:
		draw_rect(Rect2(r.position - Vector2(3, 3), r.size + Vector2(6, 6)), outline)
		draw_circle(r.position + Vector2(r.size.x, r.size.y * 0.5), 11.0, outline)
	draw_rect(r, c)
	draw_circle(r.position + Vector2(r.size.x, r.size.y * 0.5), 8.0, c)

func _draw_face(hc: Vector2, lean: float) -> void:
	var dark: Color = Color(0.08, 0.05, 0.1)
	var ex: float = 9.0
	var ey: float = -4.0
	var mood: String = face_mood
	if state in ["down", "ko", "launched"]:
		mood = "dizzy"
	elif state == "win":
		mood = "happy"
	elif state == "lose":
		mood = "sad"
	elif state == "hit":
		mood = "ouch"
	elif state == "attack":
		mood = "yell"
	elif state == "block":
		mood = "brace"
	else:
		mood = "fierce"
	# eyes
	for i: int in range(2):
		var cx: float = hc.x + 4.0 + (i - 0.5) * 2.0 * ex
		var e: Vector2 = Vector2(cx, hc.y + ey)
		if mood == "dizzy":
			draw_line(e + Vector2(-5, -5), e + Vector2(5, 5), dark, 3.0)
			draw_line(e + Vector2(-5, 5), e + Vector2(5, -5), dark, 3.0)
		elif mood == "happy":
			draw_arc(e, 6.0, PI, TAU, 8, dark, 3.0)
		elif mood == "brace":
			draw_line(e + Vector2(-6, 0), e + Vector2(6, 0), dark, 3.0)
		else:
			draw_circle(e, 7.0, Color.WHITE)
			draw_circle(e + Vector2(2.5, 0.5), 3.6, dark)
			draw_circle(e + Vector2(1.2, -1.2), 1.2, Color.WHITE)
	# brows
	if mood in ["fierce", "yell", "brace"]:
		draw_line(hc + Vector2(-8, -14), hc + Vector2(0, -10), dark, 3.5)
		draw_line(hc + Vector2(10, -11), hc + Vector2(19, -15), dark, 3.5)
	elif mood == "ouch":
		draw_line(hc + Vector2(-8, -11), hc + Vector2(0, -15), dark, 3.5)
		draw_line(hc + Vector2(10, -15), hc + Vector2(19, -12), dark, 3.5)
	# mouth
	var m: Vector2 = hc + Vector2(8, 11)
	match mood:
		"fierce":
			draw_line(m + Vector2(-7, 0), m + Vector2(6, -1), dark, 3.0)
		"yell":
			draw_circle(m, 6.5, dark)
			draw_circle(m + Vector2(0, 2), 3.0, Color(0.9, 0.3, 0.4))
		"ouch":
			draw_circle(m, 5.0, dark)
		"happy":
			draw_arc(m + Vector2(0, -3), 8.0, 0.2, PI - 0.2, 10, dark, 3.0)
		"sad":
			draw_arc(m + Vector2(0, 5), 8.0, PI + 0.3, TAU - 0.3, 10, dark, 3.0)
		"dizzy":
			draw_arc(m + Vector2(0, 2), 6.0, PI + 0.4, TAU - 0.4, 8, dark, 3.0)
		"brace":
			draw_line(m + Vector2(-6, 0), m + Vector2(6, 0), dark, 3.0)
	# cheek
	draw_circle(hc + Vector2(-14, 8), 4.0, Color(1, 0.5, 0.5, 0.35))

func _draw_hair(hc: Vector2, c: Color, outline: Color, skin: Color) -> void:
	var style: String = String(data.get("hairstyle", "flat"))
	var acc: Color = col(data["accent"])
	match style:
		"flat":
			var pts: PackedVector2Array = PackedVector2Array([hc + Vector2(-28, -6), hc + Vector2(-22, -26), hc + Vector2(0, -32), hc + Vector2(24, -26), hc + Vector2(30, -8), hc + Vector2(18, -16), hc + Vector2(-4, -20), hc + Vector2(-22, -12)])
			draw_colored_polygon(pts, c)
		"spiky":
			var pts: PackedVector2Array = PackedVector2Array([hc + Vector2(-28, -4), hc + Vector2(-30, -30), hc + Vector2(-14, -22), hc + Vector2(-8, -46), hc + Vector2(2, -24), hc + Vector2(14, -48), hc + Vector2(18, -22), hc + Vector2(34, -36), hc + Vector2(28, -8), hc + Vector2(10, -16), hc + Vector2(-12, -16)])
			draw_colored_polygon(pts, outline)
			var inner: PackedVector2Array = PackedVector2Array()
			for v: Vector2 in pts:
				inner.append(hc + (v - hc) * 0.9)
			draw_colored_polygon(inner, c)
		"ponytail":
			draw_colored_polygon(PackedVector2Array([hc + Vector2(-28, -4), hc + Vector2(-24, -26), hc + Vector2(4, -32), hc + Vector2(28, -22), hc + Vector2(30, -6), hc + Vector2(12, -18), hc + Vector2(-14, -16)]), c)
			var tail: Vector2 = hc + Vector2(-30, -18)
			var sway: float = sin(life_t * 7.0) * 8.0
			draw_line(tail, tail + Vector2(-22, 22 + sway), outline, 15.0)
			draw_line(tail, tail + Vector2(-22, 22 + sway), c, 9.0)
			draw_circle(tail + Vector2(-22, 22 + sway), 7.0, outline)
			draw_circle(tail + Vector2(-22, 22 + sway), 5.0, c)
			draw_line(hc + Vector2(-28, -12), hc + Vector2(28, -12), acc, 5.0)
		"mask":
			draw_colored_polygon(PackedVector2Array([hc + Vector2(-27, -8), hc + Vector2(-26, -28), hc + Vector2(0, -32), hc + Vector2(26, -28), hc + Vector2(28, -8), hc + Vector2(22, -4), hc + Vector2(14, -8), hc + Vector2(2, -4), hc + Vector2(-10, -8), hc + Vector2(-20, -4)]), col(data["torso"]))
			_draw_star(hc + Vector2(2, -22), 7.0, acc, 0.0)
		"mohawk":
			draw_colored_polygon(PackedVector2Array([hc + Vector2(-8, -24), hc + Vector2(-4, -58), hc + Vector2(2, -34), hc + Vector2(8, -60), hc + Vector2(12, -34), hc + Vector2(20, -52), hc + Vector2(18, -22)]), outline)
