class_name Fx
extends Node2D
## Hit sparks, comic words, dust, rings. All drawn in world space.

var items: Array = []
var font: Font = null

func _ready() -> void:
	z_index = 20
	font = load("res://assets/fonts/bangers.ttf")

func spark(p: Vector2, color: Color, big: bool = false) -> void:
	items.append({"k": "spark", "p": p, "t": 0.0, "life": 0.28 if not big else 0.4, "c": color, "r": randf_range(0.0, TAU), "big": big})
	for i: int in range(8 if not big else 14):
		var ang: float = randf_range(0.0, TAU)
		var sp: float = randf_range(260.0, 620.0) * (1.4 if big else 1.0)
		items.append({"k": "dot", "p": p, "v": Vector2(cos(ang), sin(ang)) * sp, "t": 0.0, "life": randf_range(0.25, 0.5), "c": color, "r": randf_range(4.0, 9.0)})

func word(p: Vector2, text: String, color: Color, scale: float = 1.0) -> void:
	items.append({"k": "word", "p": p, "t": 0.0, "life": 0.7, "text": text, "c": color, "s": scale, "rot": randf_range(-0.25, 0.25), "v": Vector2(randf_range(-60, 60), -180)})

func dust(p: Vector2, n: int = 6, spread: float = 60.0) -> void:
	for i: int in range(n):
		items.append({"k": "dust", "p": p + Vector2(randf_range(-spread, spread), 0), "v": Vector2(randf_range(-120, 120), randf_range(-140, -40)), "t": 0.0, "life": randf_range(0.4, 0.7), "r": randf_range(10.0, 22.0)})

func ring(p: Vector2, color: Color, size: float = 160.0) -> void:
	items.append({"k": "ring", "p": p, "t": 0.0, "life": 0.35, "c": color, "s": size})

func block_spark(p: Vector2) -> void:
	items.append({"k": "shield", "p": p, "t": 0.0, "life": 0.25})
	for i: int in range(6):
		var ang: float = randf_range(-PI * 0.8, PI * 0.2)
		items.append({"k": "dot", "p": p, "v": Vector2(cos(ang), sin(ang)) * randf_range(200, 420), "t": 0.0, "life": 0.3, "c": Color(0.5, 0.8, 1.0), "r": 5.0})

func speedlines(p: Vector2, dir: int, color: Color) -> void:
	for i: int in range(6):
		items.append({"k": "line", "p": p + Vector2(randf_range(-40, 40) * dir, randf_range(-150, -20)), "dir": dir, "t": 0.0, "life": 0.22, "c": color, "len": randf_range(60, 160)})

func confetti(p: Vector2, n: int = 60) -> void:
	for i: int in range(n):
		var ang: float = randf_range(-PI, 0.0)
		items.append({"k": "conf", "p": p, "v": Vector2(cos(ang), sin(ang)) * randf_range(300, 900), "t": 0.0, "life": randf_range(1.2, 2.2),
			"c": [Color(1, 0.3, 0.3), Color(1, 0.9, 0.2), Color(0.3, 1, 0.5), Color(0.3, 0.6, 1), Color(1, 0.4, 0.9)][randi() % 5], "rot": randf_range(0, TAU), "w": randf_range(8, 14)})

func cloud(p: Vector2, c1: Color, c2: Color, life: float) -> void:
	items.append({"k": "cloud", "p": p, "t": 0.0, "life": life, "c1": c1, "c2": c2, "seed": randf() * 100.0})

func cloud_pos() -> Vector2:
	for it: Dictionary in items:
		if it["k"] == "cloud":
			return it["p"]
	return Vector2.ZERO

func move_cloud(p: Vector2) -> void:
	for it: Dictionary in items:
		if it["k"] == "cloud":
			it["p"] = p

func clear() -> void:
	items.clear()

func tick(dt: float) -> void:
	for i: int in range(items.size() - 1, -1, -1):
		var it: Dictionary = items[i]
		it["t"] = float(it["t"]) + dt
		if it.has("v"):
			var v: Vector2 = it["v"]
			if it["k"] == "conf":
				v.y += 900.0 * dt
				v.x *= 0.98
			elif it["k"] == "dot":
				v.y += 1200.0 * dt
			elif it["k"] == "dust":
				v *= 0.94
			it["v"] = v
			it["p"] = (it["p"] as Vector2) + v * dt
		if float(it["t"]) >= float(it["life"]):
			items.remove_at(i)
	queue_redraw()

func _draw() -> void:
	for it: Dictionary in items:
		var f: float = float(it["t"]) / float(it["life"])
		var p: Vector2 = it["p"]
		match String(it["k"]):
			"spark":
				var c: Color = it["c"]
				var big: bool = bool(it.get("big", false))
				var r: float = (60.0 if big else 40.0) * (0.6 + 0.6 * sin(f * PI))
				var rot: float = float(it["r"])
				var pts: PackedVector2Array = PackedVector2Array()
				for k: int in range(16):
					var rr: float = r if k % 2 == 0 else r * 0.4
					var a: float = rot + k * PI / 8.0
					pts.append(p + Vector2(cos(a), sin(a)) * rr)
				draw_colored_polygon(pts, Color(0.1, 0.05, 0.1, 1.0 - f))
				var inner: PackedVector2Array = PackedVector2Array()
				for v: Vector2 in pts:
					inner.append(p + (v - p) * 0.82)
				draw_colored_polygon(inner, Color(c.r, c.g, c.b, 1.0 - f * 0.7))
				var core: PackedVector2Array = PackedVector2Array()
				for v: Vector2 in pts:
					core.append(p + (v - p) * 0.45)
				draw_colored_polygon(core, Color(1, 1, 1, 1.0 - f))
			"dot":
				var c: Color = it["c"]
				draw_circle(p, float(it["r"]) * (1.0 - f), Color(c.r, c.g, c.b, 1.0 - f))
			"dust":
				draw_circle(p, float(it["r"]) * (0.5 + f), Color(0.85, 0.8, 0.7, 0.45 * (1.0 - f)))
			"ring":
				var c: Color = it["c"]
				draw_arc(p, float(it["s"]) * f, 0.0, TAU, 40, Color(c.r, c.g, c.b, 1.0 - f), 14.0 * (1.0 - f) + 2.0)
			"shield":
				var r: float = 50.0 * (0.7 + 0.5 * sin(f * PI))
				for k: int in range(6):
					var a: float = k * TAU / 6.0
					var b: float = (k + 1) * TAU / 6.0
					draw_line(p + Vector2(cos(a), sin(a)) * r, p + Vector2(cos(b), sin(b)) * r, Color(0.5, 0.85, 1.0, 1.0 - f), 7.0)
				draw_circle(p, r * 0.8, Color(0.6, 0.9, 1.0, 0.35 * (1.0 - f)))
			"line":
				var c: Color = it["c"]
				var d: float = float(it["dir"])
				draw_line(p, p + Vector2(-float(it["len"]) * d, 0), Color(c.r, c.g, c.b, (1.0 - f) * 0.8), 4.0)
			"conf":
				var c: Color = it["c"]
				var w: float = float(it["w"])
				draw_set_transform(p, float(it["rot"]) + f * 6.0, Vector2.ONE)
				draw_rect(Rect2(Vector2(-w * 0.5, -w * 0.3), Vector2(w, w * 0.6)), Color(c.r, c.g, c.b, 1.0 - f * f))
				draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)
			"cloud":
				var tt: float = float(it["t"])
				var sd: float = float(it["seed"])
				var c1: Color = it["c1"]
				var c2: Color = it["c2"]
				var cx: Vector2 = p + Vector2(0, -110)
				# puffs
				for k: int in range(14):
					var ang: float = k * TAU / 14.0 + tt * (1.5 if k % 2 == 0 else -1.2)
					var rr: float = 95.0 + 30.0 * sin(tt * 9.0 + k * 1.7 + sd)
					var pp: Vector2 = cx + Vector2(cos(ang) * rr * 1.25, sin(ang) * rr * 0.75)
					draw_circle(pp, 60.0 + 12.0 * sin(tt * 11.0 + k), Color(0.1, 0.05, 0.1))
				for k: int in range(14):
					var ang: float = k * TAU / 14.0 + tt * (1.5 if k % 2 == 0 else -1.2)
					var rr: float = 95.0 + 30.0 * sin(tt * 9.0 + k * 1.7 + sd)
					var pp: Vector2 = cx + Vector2(cos(ang) * rr * 1.25, sin(ang) * rr * 0.75)
					draw_circle(pp, 54.0 + 12.0 * sin(tt * 11.0 + k), Color(0.92, 0.88, 0.8) if k % 3 != 0 else Color(0.8, 0.76, 0.7))
				draw_circle(cx, 120.0, Color(0.92, 0.88, 0.8))
				# limbs poking out
				for k: int in range(7):
					var ang: float = tt * 7.0 + k * 0.9 + sd
					var out: Vector2 = cx + Vector2(cos(ang) * 215.0, sin(ang) * 125.0)
					var vis: float = sin(tt * 13.0 + k * 2.0)
					if vis > -0.1:
						var cc: Color = c1 if k % 2 == 0 else c2
						draw_line(cx + (out - cx) * 0.6, out, Color(0.1, 0.05, 0.1), 20.0)
						draw_line(cx + (out - cx) * 0.6, out, Color(0.95, 0.78, 0.6), 13.0)
						draw_circle(out, 19.0, Color(0.1, 0.05, 0.1))
						draw_circle(out, 15.0, cc)
				# stars
				for k: int in range(6):
					var ang: float = tt * 4.0 + k * TAU / 6.0
					var sp: Vector2 = cx + Vector2(cos(ang) * 240.0, -40.0 + sin(ang) * 130.0)
					var pts: PackedVector2Array = PackedVector2Array()
					for j: int in range(10):
						var r2: float = 14.0 if j % 2 == 0 else 6.0
						var a2: float = tt * 6.0 + j * PI / 5.0
						pts.append(sp + Vector2(cos(a2), sin(a2)) * r2)
					draw_colored_polygon(pts, Color(1.0, 0.9, 0.2))
			"word":
				var c: Color = it["c"]
				var s: float = float(it["s"]) * (1.0 + 0.5 * sin(minf(f * 3.0, 1.0) * PI * 0.5))
				var pop: float = 1.0 + 0.6 * maxf(0.0, 1.0 - f * 4.0)
				var alpha: float = 1.0 if f < 0.6 else 1.0 - (f - 0.6) / 0.4
				var text: String = it["text"]
				var fs: int = int(56.0 * s * pop)
				var width: float = font.get_string_size(text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
				draw_set_transform(p, float(it["rot"]), Vector2.ONE)
				var off: Vector2 = Vector2(-width * 0.5, 0)
				for ox: int in range(-1, 2):
					for oy: int in range(-1, 2):
						draw_string(font, off + Vector2(ox * 4, oy * 4), text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(0.1, 0.05, 0.1, alpha))
				draw_string(font, off + Vector2(0, 4), text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(c.r * 0.6, c.g * 0.6, c.b * 0.6, alpha))
				draw_string(font, off, text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(c.r, c.g, c.b, alpha))
				draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)

