class_name FighterAI
extends RefCounted
## Simple but lively opponent brain. difficulty 0..1.

var f: Fighter
var difficulty: float = 0.5
var think_t: float = 0.0
var plan: String = "approach"
var plan_t: float = 0.0
var hold: Dictionary = {}
var react_delay: float = 0.3
var jump_cd: float = 0.0
var taunt_t: float = 0.0

func _init(fighter: Fighter, diff: float) -> void:
	f = fighter
	difficulty = clampf(diff, 0.0, 1.0)
	react_delay = lerpf(0.45, 0.1, difficulty)

func blank() -> Dictionary:
	return {"left": false, "right": false, "up": false, "down": false, "punch": false, "kick": false, "special": false, "block": false}

func tick(dt: float, projectiles: Array) -> Dictionary:
	var inp: Dictionary = blank()
	var o: Fighter = f.opponent
	if o == null:
		return inp
	think_t -= dt
	plan_t -= dt
	jump_cd -= dt
	var dx: float = (o.pos.x - f.pos.x) * f.facing  # positive = opponent is in front
	var dist: float = absf(o.pos.x - f.pos.x)
	var fwd: String = "right" if f.facing == 1 else "left"
	var back: String = "left" if f.facing == 1 else "right"
	# incoming projectile?
	var danger: bool = false
	for p: Projectile in projectiles:
		if p.owner_f != f and p.dir == -f.facing and (p.pos.x - f.pos.x) * f.facing > 0.0 and absf(p.pos.x - f.pos.x) < 260.0:
			danger = true
	if danger and f.on_ground and jump_cd <= 0.0 and randf() < lerpf(0.4, 0.95, difficulty):
		inp["up"] = true
		inp[fwd] = true
		jump_cd = 0.8
		return inp
	# react to opponent attacking
	var opp_attacking: bool = o.state == "attack" and dist < 230.0
	if opp_attacking and f.can_act() and f.on_ground:
		if randf() < lerpf(0.12, 0.8, difficulty) * dt * 14.0:
			var low: bool = bool(o.attack.get("crouch", false))
			plan = "block_low" if low else "block"
			plan_t = randf_range(0.25, 0.6)
	if think_t <= 0.0:
		think_t = randf_range(0.08, 0.3) * lerpf(1.6, 0.7, difficulty)
		if plan_t <= 0.0:
			_choose(dist, o)
	match plan:
		"approach":
			inp[fwd] = true
		"retreat":
			inp[back] = true
		"block":
			inp["block"] = true
		"block_low":
			inp["block"] = true
			inp["down"] = true
		"jumpin":
			if f.on_ground and jump_cd <= 0.0:
				inp["up"] = true
				inp[fwd] = true
				jump_cd = 0.9
			elif not f.on_ground and dist < 170.0 and randf() < 0.3:
				inp["kick"] = true
		"punch":
			if dist < 150.0:
				inp["punch"] = true
				if f.state == "attack" and f.attack_hit:
					inp["punch"] = randf() < 0.9
					if randf() < 0.3:
						inp["kick"] = true
			else:
				inp[fwd] = true
		"kick":
			if dist < 170.0:
				inp["kick"] = true
			else:
				inp[fwd] = true
		"sweep":
			if dist < 150.0:
				inp["down"] = true
				inp["kick"] = true
			else:
				inp[fwd] = true
		"special":
			var sp: String = String(f.data.get("special", "dash"))
			var want: bool = true
			if sp in ["rising", "spin"] and dist > 200.0:
				want = false
				inp[fwd] = true
			if sp in ["fireball", "shock"] and dist < 180.0:
				want = randf() < 0.5
			if want:
				inp["special"] = true
				plan = "wait"
				plan_t = 0.3
		"wait":
			pass
		"crouch":
			inp["down"] = true
	return inp

func _choose(dist: float, o: Fighter) -> void:
	var r: float = randf()
	var sp: String = String(f.data.get("special", "dash"))
	if o.is_down():
		plan = "retreat" if r < 0.3 else "wait"
		plan_t = 0.4
		return
	if f.meter >= 50.0 and r < lerpf(0.12, 0.35, difficulty):
		plan = "special"
		plan_t = 0.5
		return
	if dist > 240.0:
		if r < 0.14 + 0.1 * difficulty:
			plan = "jumpin"
			plan_t = 0.8
		elif r < 0.22 and sp in ["fireball", "shock"] and f.meter >= 50.0:
			plan = "special"
			plan_t = 0.5
		else:
			plan = "approach"
			plan_t = randf_range(0.2, 0.6)
	elif dist > 150.0:
		if r < 0.55:
			plan = "approach"
			plan_t = 0.2
		elif r < 0.7:
			plan = "kick"
			plan_t = 0.4
		elif r < 0.8:
			plan = "jumpin"
			plan_t = 0.8
		else:
			plan = "wait"
			plan_t = 0.25
	else:
		if r < 0.4 + 0.15 * difficulty:
			plan = "punch"
			plan_t = randf_range(0.5, 1.0)
		elif r < 0.6 + 0.1 * difficulty:
			plan = "kick"
			plan_t = 0.4
		elif r < 0.72:
			plan = "sweep"
			plan_t = 0.4
		elif r < 0.85:
			plan = "block"
			plan_t = randf_range(0.3, 0.7)
		else:
			plan = "retreat"
			plan_t = randf_range(0.2, 0.5)

