class_name Sfx
extends Node
## Sound + music manager with a small player pool.

var streams: Dictionary = {}
var pool: Array = []
var music: AudioStreamPlayer
var music_name: String = ""
var sound_on: bool = true
var music_on: bool = true
var music_vol: float = -6.0

const NAMES: Array = ["whoosh", "whoosh_big", "punch1", "punch2", "punch3", "kick", "block", "bonk", "boing",
	"jump", "land", "zap", "fireball", "dash", "shock", "uppercut", "dizzy", "bell", "bell3", "cheer", "ooh",
	"click", "select", "ding", "ko", "meter", "step", "music_fight", "music_fight2", "music_menu", "music_win", "music_lose"]

func _ready() -> void:
	for n: String in NAMES:
		var path: String = "res://assets/sfx/%s.ogg" % n
		if ResourceLoader.exists(path):
			streams[n] = load(path)
	for i: int in range(12):
		var p := AudioStreamPlayer.new()
		p.bus = "Master"
		add_child(p)
		pool.append(p)
	music = AudioStreamPlayer.new()
	music.volume_db = music_vol
	add_child(music)

func play(name: String, vol_db: float = 0.0, pitch: float = 1.0) -> void:
	if not sound_on or not streams.has(name):
		return
	var p: AudioStreamPlayer = null
	for c: AudioStreamPlayer in pool:
		if not c.playing:
			p = c
			break
	if p == null:
		p = pool[randi() % pool.size()]
	p.stream = streams[name]
	p.volume_db = vol_db
	p.pitch_scale = pitch
	p.play()

func play_var(name: String, vol_db: float = 0.0) -> void:
	play(name, vol_db, randf_range(0.92, 1.08))

func play_music(name: String, loop: bool = true) -> void:
	if name == music_name and music.playing:
		return
	music_name = name
	if not streams.has(name):
		return
	var s: AudioStream = streams[name]
	if s is AudioStreamOggVorbis:
		(s as AudioStreamOggVorbis).loop = loop
	music.stream = s
	music.volume_db = music_vol if music_on else -80.0
	music.play()

func stop_music() -> void:
	music.stop()
	music_name = ""

func set_music_on(v: bool) -> void:
	music_on = v
	music.volume_db = music_vol if music_on else -80.0

func set_sound_on(v: bool) -> void:
	sound_on = v

