#!/usr/bin/env python3
"""Synthesize all sounds + music for Knuckle Kings. Writes WAV to assets/sfx, then ffmpeg -> OGG."""
import math, os, random, subprocess, struct
import numpy as np

SR = 22050
OUT = os.path.join(os.path.dirname(__file__), "..", "assets", "sfx")
os.makedirs(OUT, exist_ok=True)
random.seed(7); np.random.seed(7)

def t(n): return np.arange(n) / SR
def env(n, a=0.005, d=0.1, s=0.0, r=0.05, hold=0.0):
    a_n, d_n, r_n, h_n = int(a*SR), int(d*SR), int(r*SR), int(hold*SR)
    e = np.concatenate([np.linspace(0, 1, a_n), np.linspace(1, s, d_n), np.full(h_n, s), np.linspace(s, 0, r_n)])
    if len(e) < n:
        e = np.concatenate([e, np.zeros(n-len(e))])
    return e[:n]
def noise(n): return np.random.uniform(-1, 1, n)
def lowpass(x, cutoff):
    rc = 1.0 / (2*math.pi*cutoff); dt = 1.0/SR; a = dt/(rc+dt)
    y = np.zeros_like(x); acc = 0.0
    for i in range(len(x)):
        acc += a*(x[i]-acc); y[i] = acc
    return y
def highpass(x, cutoff):
    return x - lowpass(x, cutoff)
def sine(f, n, ph=0): return np.sin(2*math.pi*f*t(n)+ph)
def sweep(f0, f1, n, shape="sin"):
    tt = t(n); f = f0 + (f1-f0)*(tt/tt[-1])
    ph = 2*math.pi*np.cumsum(f)/SR
    if shape == "sin": return np.sin(ph)
    if shape == "saw": return 2*((ph/(2*math.pi)) % 1)-1
    if shape == "sq": return np.sign(np.sin(ph))
    return np.sin(ph)
def clip(x, g=1.0): return np.tanh(x*g)
def norm(x, p=0.9):
    m = np.max(np.abs(x)) or 1
    return x/m*p
def write(name, x, stereo=None):
    x = np.clip(x, -1, 1)
    path = os.path.join(OUT, name + ".wav")
    with open(path, "wb") as f:
        data = (x*32767).astype("<i2").tobytes()
        f.write(b"RIFF"+struct.pack("<I", 36+len(data))+b"WAVEfmt "+struct.pack("<IHHIIHH", 16, 1, 1, SR, SR*2, 2, 16)+b"data"+struct.pack("<I", len(data))+data)
    return path

# ---------------- SFX ----------------
def whoosh(n_s=0.18, f0=1800, f1=400):
    n = int(n_s*SR)
    x = lowpass(noise(n), 2500) * env(n, 0.02, n_s-0.03, 0, 0.01)
    x = highpass(x, 300)
    return norm(x, 0.6)

def punch(strength=1.0, n_s=0.16):
    n = int(n_s*SR)
    thud = sweep(160*strength, 55, n) * env(n, 0.002, 0.09, 0.0, 0.02)
    snap = highpass(noise(n), 1500) * env(n, 0.001, 0.03, 0, 0.01)
    body = lowpass(noise(n), 600) * env(n, 0.002, 0.07, 0, 0.02)
    return norm(clip(thud*1.2 + snap*0.6 + body*0.8, 1.6), 0.85)

def kick():
    n = int(0.22*SR)
    thud = sweep(120, 40, n) * env(n, 0.002, 0.14, 0.0, 0.03)
    body = lowpass(noise(n), 400) * env(n, 0.002, 0.1, 0, 0.02)
    return norm(clip(thud*1.3 + body, 1.8), 0.9)

def block():
    n = int(0.14*SR)
    x = sweep(900, 300, n, "sq")*0.3*env(n, 0.001, 0.06, 0, 0.02) + highpass(noise(n), 2000)*env(n, 0.001, 0.04, 0, 0.01)*0.5
    return norm(x, 0.6)

def bonk():
    n = int(0.3*SR)
    x = sweep(700, 250, n)*env(n, 0.002, 0.2, 0.0, 0.05) + sine(1400, n)*0.3*env(n, 0.001, 0.05, 0, 0.01)
    return norm(clip(x, 1.4), 0.8)

def boing():
    n = int(0.4*SR)
    tt = t(n); f = 300 + 200*np.sin(2*math.pi*9*tt)*np.exp(-tt*4)
    ph = 2*math.pi*np.cumsum(f)/SR
    return norm(np.sin(ph)*env(n, 0.005, 0.3, 0.1, 0.08), 0.7)

def jump():
    n = int(0.2*SR)
    return norm(sweep(300, 800, n)*env(n, 0.01, 0.15, 0, 0.03), 0.5)

def land():
    n = int(0.12*SR)
    return norm(lowpass(noise(n), 500)*env(n, 0.002, 0.08, 0, 0.02)+sweep(120, 60, n)*0.5*env(n, 0.002, 0.08, 0, 0.02), 0.6)

def zap():
    n = int(0.35*SR)
    x = sweep(1200, 200, n, "saw")*env(n, 0.005, 0.25, 0.1, 0.05)*0.6 + sine(90, n)*0.4*env(n, 0.01, 0.2, 0, 0.05)
    x += highpass(noise(n), 3000)*0.3*env(n, 0.001, 0.1, 0, 0.02)
    return norm(clip(x, 1.5), 0.8)

def fireball():
    n = int(0.6*SR)
    tt = t(n)
    x = lowpass(noise(n), 1200)*env(n, 0.05, 0.4, 0.2, 0.1)
    x += np.sin(2*math.pi*(220+80*np.sin(2*math.pi*6*tt))*tt)*0.4*env(n, 0.02, 0.4, 0.2, 0.1)
    return norm(x, 0.7)

def dash():
    n = int(0.3*SR)
    x = lowpass(noise(n), 1800)*env(n, 0.01, 0.25, 0.0, 0.03) + sweep(200, 600, n, "saw")*0.3*env(n, 0.01, 0.2, 0, 0.05)
    return norm(x, 0.6)

def shock():
    n = int(0.6*SR)
    x = sweep(80, 30, n)*env(n, 0.002, 0.45, 0, 0.1) + lowpass(noise(n), 300)*env(n, 0.002, 0.3, 0, 0.1)
    return norm(clip(x, 2.0), 0.95)

def uppercut():
    n = int(0.4*SR)
    x = sweep(200, 1200, n)*env(n, 0.01, 0.3, 0, 0.05)*0.5 + lowpass(noise(n), 2000)*env(n, 0.01, 0.2, 0, 0.05)
    return norm(x, 0.7)

def dizzy():
    n = int(1.6*SR); tt = t(n)
    f = 500 + 150*np.sin(2*math.pi*3*tt)
    ph = 2*math.pi*np.cumsum(f)/SR
    x = np.sin(ph)*0.5 + np.sin(ph*2.01)*0.2
    return norm(x*env(n, 0.05, 1.3, 0.3, 0.2), 0.5)

def bell(hits=1):
    n = int(1.2*SR)
    x = np.zeros(n)
    for i in range(hits):
        s = int(i*0.35*SR)
        seg = n - s
        ring = (sine(1046, seg)*0.6 + sine(2093*1.01, seg)*0.3 + sine(3150, seg)*0.15) * env(seg, 0.002, 0.9, 0.0, 0.2)
        x[s:] += ring
    return norm(x, 0.7)

def crowd_cheer(n_s=2.2):
    n = int(n_s*SR)
    base = lowpass(noise(n), 900)
    tt = t(n)
    mod = 0.6 + 0.4*np.sin(2*math.pi*2.3*tt) * np.sin(2*math.pi*0.7*tt+1)
    x = base*mod*env(n, 0.15, 1.2, 0.5, 0.8)
    # voices
    for _ in range(14):
        f = random.uniform(180, 420); s = random.randint(0, n//3); l = random.randint(int(0.3*SR), int(1.2*SR))
        l = min(l, n-s)
        x[s:s+l] += sweep(f, f*random.uniform(0.8, 1.3), l)*0.08*env(l, 0.05, l/SR*0.6, 0.3, 0.1)
    return norm(x, 0.55)

def crowd_ooh():
    n = int(0.9*SR)
    x = np.zeros(n)
    for _ in range(10):
        f = random.uniform(200, 330)
        x += sweep(f, f*0.85, n)*0.1*env(n, 0.05, 0.6, 0.2, 0.2)
    x += lowpass(noise(n), 700)*0.3*env(n, 0.05, 0.5, 0.3, 0.3)
    return norm(x, 0.5)

def ui_click():
    n = int(0.08*SR)
    return norm(sine(900, n)*env(n, 0.001, 0.05, 0, 0.02) + sine(1350, n)*0.4*env(n, 0.001, 0.03, 0, 0.01), 0.5)

def ui_select():
    n = int(0.25*SR)
    x = np.zeros(n)
    for i, f in enumerate([523, 659, 784]):
        s = int(i*0.05*SR); seg = n-s
        x[s:] += sine(f, seg)*env(seg, 0.002, 0.15, 0, 0.05)*0.5
    return norm(x, 0.6)

def round_voice_bell():
    n = int(0.5*SR)
    x = sine(880, n)*env(n, 0.002, 0.4, 0, 0.1) + sine(1320, n)*0.4*env(n, 0.002, 0.3, 0, 0.1)
    return norm(x, 0.6)

def ko_hit():
    n = int(0.9*SR)
    x = sweep(140, 35, n)*env(n, 0.002, 0.6, 0.0, 0.2)*1.2 + lowpass(noise(n), 500)*env(n, 0.002, 0.3, 0, 0.1)
    x += sine(60, n)*0.5*env(n, 0.01, 0.5, 0, 0.2)
    return norm(clip(x, 2.0), 0.95)

def meter_full():
    n = int(0.5*SR)
    x = np.zeros(n)
    for i, f in enumerate([659, 880, 1174, 1568]):
        s = int(i*0.07*SR); seg = n-s
        x[s:] += sine(f, seg)*env(seg, 0.002, 0.25, 0, 0.1)*0.4
    return norm(x, 0.6)

def footstep():
    n = int(0.07*SR)
    return norm(lowpass(noise(n), 700)*env(n, 0.002, 0.05, 0, 0.01), 0.3)

sfx = {
    "whoosh": whoosh(), "whoosh_big": whoosh(0.26, 1200, 250),
    "punch1": punch(1.0), "punch2": punch(1.25, 0.18), "punch3": punch(0.8, 0.13),
    "kick": kick(), "block": block(), "bonk": bonk(), "boing": boing(),
    "jump": jump(), "land": land(), "zap": zap(), "fireball": fireball(), "dash": dash(),
    "shock": shock(), "uppercut": uppercut(), "dizzy": dizzy(),
    "bell": bell(1), "bell3": bell(3), "cheer": crowd_cheer(), "ooh": crowd_ooh(),
    "click": ui_click(), "select": ui_select(), "ding": round_voice_bell(), "ko": ko_hit(),
    "meter": meter_full(), "step": footstep(),
}

# ---------------- MUSIC ----------------
def note(f, n, kind="saw", vib=0.0):
    tt = t(n)
    if vib: f = f*(1+0.01*np.sin(2*math.pi*5*tt))
    ph = 2*math.pi*np.cumsum(np.full(n, f) if np.isscalar(f) else f)/SR
    if kind == "saw": return 2*((ph/(2*math.pi)) % 1)-1
    if kind == "sq": return np.sign(np.sin(ph))
    if kind == "tri": return 2*np.abs(2*((ph/(2*math.pi)) % 1)-1)-1
    return np.sin(ph)

def midi(m): return 440*2**((m-69)/12)

def drum_kick(n):
    return sweep(150, 45, n)*env(n, 0.001, 0.12, 0, 0.05)*1.2
def drum_snare(n):
    return (highpass(noise(n), 1200)*0.8 + sine(190, n)*0.4)*env(n, 0.001, 0.09, 0, 0.05)
def drum_hat(n, open_=False):
    return highpass(noise(n), 6000)*env(n, 0.001, 0.12 if open_ else 0.03, 0, 0.01)*0.5

def make_track(bpm, bars, bass_pat, lead_pat, chords, drum_style="rock", swing=0.0, lead_kind="sq", gain=0.9):
    beat = 60.0/bpm; step = beat/4
    n = int(bars*4*beat*SR)
    mix = np.zeros(n + SR)
    # drums
    for bar in range(bars):
        for s in range(16):
            at = int((bar*16+s)*step*SR + (swing*step*SR if s % 2 else 0))
            if drum_style == "rock":
                if s in (0, 8, 10): mix[at:at+int(0.3*SR)] += drum_kick(int(0.3*SR))
                if s in (4, 12): mix[at:at+int(0.2*SR)] += drum_snare(int(0.2*SR))
                if s % 2 == 0: mix[at:at+int(0.1*SR)] += drum_hat(int(0.1*SR), s % 4 == 2 and s % 8 == 6)
            elif drum_style == "fast":
                if s in (0, 6, 8, 14): mix[at:at+int(0.3*SR)] += drum_kick(int(0.3*SR))
                if s in (4, 12): mix[at:at+int(0.2*SR)] += drum_snare(int(0.2*SR))
                if s % 2 == 1 and bar % 2 == 1 and s > 11: mix[at:at+int(0.2*SR)] += drum_snare(int(0.2*SR))*0.5
                mix[at:at+int(0.1*SR)] += drum_hat(int(0.1*SR), s % 4 == 2)*0.8
            elif drum_style == "menu":
                if s in (0, 10): mix[at:at+int(0.3*SR)] += drum_kick(int(0.3*SR))*0.8
                if s in (4, 12): mix[at:at+int(0.2*SR)] += drum_snare(int(0.2*SR))*0.6
                if s % 2 == 0: mix[at:at+int(0.1*SR)] += drum_hat(int(0.1*SR), False)*0.5
    # bass
    for bar in range(bars):
        root = chords[bar % len(chords)]
        for s, deg in enumerate(bass_pat):
            if deg is None: continue
            at = int((bar*16+s)*step*SR); ln = int(step*SR*0.95)
            f = midi(root-12+deg)
            mix[at:at+ln] += lowpass(note(f, ln, "saw"), 500)*env(ln, 0.005, step*0.5, 0.5, 0.02)*0.55
    # chords (pad)
    for bar in range(bars):
        root = chords[bar % len(chords)]
        ln = int(4*beat*SR)
        at = int(bar*16*step*SR)
        pad = np.zeros(ln)
        for iv in (0, 3 if bar % 4 in (1, 3) else 4, 7):
            pad += note(midi(root+iv), ln, "saw", vib=1)*0.12
        mix[at:at+ln] += lowpass(pad, 1400)*env(ln, 0.05, 1.0, 0.7, 0.3)
    # lead
    for bar in range(bars):
        root = chords[bar % len(chords)]
        pat = lead_pat[bar % len(lead_pat)]
        for s, deg in enumerate(pat):
            if deg is None: continue
            at = int((bar*16+s)*step*SR); ln = int(step*SR*0.9)
            f = midi(root+12+deg)
            mix[at:at+ln] += note(f, ln, lead_kind, vib=1)*env(ln, 0.005, step*0.4, 0.5, 0.03)*0.22
    x = mix[:n]
    # loop-friendly: crossfade tail of last beat
    x = clip(x, 1.3)
    return norm(x, gain)

E = 40  # E2
fight_chords = [E, E, E+3, E+5, E, E, E+10, E+7]
bass_rock = [0, None, 0, 0, None, 0, 0, None, 0, None, 0, 0, 7, None, 5, 3]
lead_rock = [
    [12, None, None, 10, None, 12, None, None, 7, None, None, None, 10, None, 12, None],
    [None]*16,
    [15, None, 12, None, None, 10, None, None, 12, None, None, None, None, None, None, None],
    [7, None, None, 10, None, None, 12, None, None, None, 15, None, 12, None, 10, None],
]
music_fight = make_track(150, 8, bass_rock, lead_rock, fight_chords, "rock", lead_kind="sq")
music_fight2 = make_track(170, 8, bass_rock, lead_rock, [E+5, E+5, E+8, E+10, E+5, E+3, E+1, E], "fast", lead_kind="saw", gain=0.9)
menu_chords = [45, 50, 48, 52]
bass_menu = [0, None, None, 0, None, None, 0, None, None, None, 7, None, None, 5, None, None]
lead_menu = [[12, None, None, None, 14, None, None, None, 15, None, None, None, 14, None, 12, None],
             [None]*16]
music_menu = make_track(105, 8, bass_menu, lead_menu, menu_chords, "menu", lead_kind="tri", gain=0.75)
win_n = int(2.2*SR)
win = np.zeros(win_n)
for i, m in enumerate([64, 68, 71, 76, 75, 76]):
    s = int(i*0.17*SR) if i < 4 else int((0.68 + (i-4)*0.35)*SR)
    seg = win_n - s
    win[s:] += note(midi(m), seg, "sq")*env(seg, 0.005, 0.6 if i >= 4 else 0.2, 0.3 if i >= 4 else 0, 0.3)*0.25
    win[s:] += note(midi(m-12), seg, "saw")*env(seg, 0.005, 0.6 if i >= 4 else 0.2, 0.3 if i >= 4 else 0, 0.3)*0.15
music_win = norm(clip(win, 1.2), 0.8)
lose_n = int(2.0*SR)
lose = np.zeros(lose_n)
for i, m in enumerate([64, 63, 62, 59]):
    s = int(i*0.4*SR); seg = lose_n - s
    lose[s:] += note(midi(m), seg, "tri", vib=1)*env(seg, 0.01, 0.6, 0.3, 0.4)*0.3
music_lose = norm(lose, 0.7)

sfx.update({"music_fight": music_fight, "music_fight2": music_fight2, "music_menu": music_menu,
            "music_win": music_win, "music_lose": music_lose})

